static void managed_resize(std::vector<uint8_t>& out,const std::vector<uint8_t>& src,unsigned sw,unsigned sh,unsigned w,unsigned h){out.assign(size_t(w)*h*4,0);if(src.size()!=size_t(sw)*sh*4)return;for(unsigned y=0;y<h;++y)for(unsigned x=0;x<w;++x){auto sx=std::min(sw-1,unsigned((uint64_t(x)*sw)/w)),sy=std::min(sh-1,unsigned((uint64_t(y)*sh)/h));memcpy(out.data()+(size_t(y)*w+x)*4,src.data()+(size_t(sy)*sw+sx)*4,4);}}
// Fit the complete chosen layout into the physical display, using one scale
// for both axes. A portrait layout on a wide panel is pillarboxed, not stretched.
static void managed_fit(std::vector<uint8_t>& out,const std::vector<uint8_t>& src,unsigned sw,unsigned sh,unsigned w,unsigned h,bool opaque=false){out.assign(size_t(w)*h*4,opaque?5:0);if(opaque)for(size_t p=3;p<out.size();p+=4)out[p]=255;if(!sw||!sh)return;const double scale=std::min(double(w)/sw,double(h)/sh);unsigned fw=std::max(1u,unsigned(std::lround(sw*scale))),fh=std::max(1u,unsigned(std::lround(sh*scale)));overlay_blit(out,src,sw,sh,{int(w-fw)/2,int(h-fh)/2,int(fw),int(fh)},int(w),int(h));}
